    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = [v for v in counts if v != background]
    if not foreground:
        return out
    marker = foreground[0]
    h, w = len(grid), len(grid[0])

    # Horizontal stroke rows have at least one adjacent pair.
    active_rows = [r for r in range(h) if any(
        grid[r][c] == marker and grid[r][c + 1] == marker
        for c in range(w - 1)
    )]

    # A vertical stroke is a column with at least three marker endpoints.
    # Markers internal to a horizontal run are not endpoints; isolated marks
    # count as endpoints.
    active_cols = []
    for c in range(w):
        endpoint_rows = []
        for r in range(h):
            if grid[r][c] != marker:
                continue
            left_end = c == 0 or grid[r][c - 1] != marker
            right_end = c == w - 1 or grid[r][c + 1] != marker
            if left_end or right_end:
                endpoint_rows.append(r)
        if len(endpoint_rows) >= 3:
            active_cols.append(c)

    # Fill selected lines to closure; intersections can extend the span of a
    # stroke already selected from the original grid.
    changed = True
    while changed:
        changed = False
        for r in active_rows:
            cols = [c for c in range(w) if out[r][c] != background]
            if cols:
                for c in range(min(cols), max(cols) + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
                        changed = True
        for c in active_cols:
            rows = [r for r in range(h) if out[r][c] != background]
            if rows:
                for r in range(min(rows), max(rows) + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
                        changed = True

    # When two vertical strokes share a top or bottom endpoint, connect them
    # across that row even if the row itself has no adjacent marker pair.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) != 2:
            continue
        a, b = cols
        if a not in active_cols or b not in active_cols:
            continue
        rows_a = [rr for rr in range(h) if grid[rr][a] == marker]
        rows_b = [rr for rr in range(h) if grid[rr][b] == marker]
        if (r == min(rows_a) == min(rows_b)) or (r == max(rows_a) == max(rows_b)):
            if any(a < c < b for c in active_cols):
                continue
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
